        <line x1="55" y1="36" x2="57" y2="18" stroke={color} strokeWidth="3.5" strokeLinecap="round"/>
        <line x1="62" y1="36" x2="67" y2="22" stroke={color} strokeWidth="3.5" strokeLinecap="round"/>
        
