// client/src/components/MobileNav.jsx
import { useState, useEffect } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import {
	Paper,
	BottomNavigation,
	BottomNavigationAction,
	Box,
} from "@mui/material";

// Sleek Icons
const HomeIcon = () => (
	<svg
		width="24"
		height="24"
		viewBox="0 0 24 24"
		fill="none"
		stroke="currentColor"
		strokeWidth="2"
		strokeLinecap="round"
		strokeLinejoin="round"
	>
		<path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"></path>
		<polyline points="9 22 9 12 15 12 15 22"></polyline>
	</svg>
);
const ForumIcon = () => (
	<svg
		width="24"
		height="24"
		viewBox="0 0 24 24"
		fill="none"
		stroke="currentColor"
		strokeWidth="2"
		strokeLinecap="round"
		strokeLinejoin="round"
	>
		<path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z"></path>
	</svg>
);
const ProfileIcon = () => (
	<svg
		width="24"
		height="24"
		viewBox="0 0 24 24"
		fill="none"
		stroke="currentColor"
		strokeWidth="2"
		strokeLinecap="round"
		strokeLinejoin="round"
	>
		<path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path>
		<circle cx="12" cy="7" r="4"></circle>
	</svg>
);

export default function MobileNav() {
	const navigate = useNavigate();
	const location = useLocation();
	const [value, setValue] = useState(0);

	const currentUser = JSON.parse(localStorage.getItem("user"));

	// Sync the active tab with the current URL
	useEffect(() => {
		if (location.pathname === "/") setValue(0);
		else if (location.pathname.startsWith("/forum")) setValue(1);
		else if (location.pathname.startsWith("/profile")) setValue(2);
	}, [location.pathname]);

	if (!currentUser) return null; // Don't show nav if not logged in

	return (
		<Paper
			elevation={8}
			sx={{
				position: "fixed",
				bottom: 0,
				left: 0,
				right: 0,
				zIndex: 1000,
				display: { xs: "block", md: "none" }, // HIDDEN ON LAPTOPS!
				borderTop: "1px solid #e0e0e0",
				pb: "env(safe-area-inset-bottom)", // Fixes overlapping on iPhones with the home bar
			}}
		>
			<BottomNavigation
				showLabels
				value={value}
				onChange={(event, newValue) => {
					setValue(newValue);
					if (newValue === 0) navigate("/");
					if (newValue === 1) navigate("/forum");
					if (newValue === 2) navigate(`/profile/${currentUser.id}`);
				}}
				sx={{
					height: 65,
					"& .MuiBottomNavigationAction-root": {
						color: "text.secondary",
						minWidth: 0,
					},
					"& .Mui-selected": {
						color: "primary.main",
						fontWeight: "bold",
					},
				}}
			>
				<BottomNavigationAction
					label="Dashboard"
					icon={
						<Box sx={{ mb: 0.5 }}>
							<HomeIcon />
						</Box>
					}
				/>
				<BottomNavigationAction
					label="Forum"
					icon={
						<Box sx={{ mb: 0.5 }}>
							<ForumIcon />
						</Box>
					}
				/>
				<BottomNavigationAction
					label="Profile"
					icon={
						<Box sx={{ mb: 0.5 }}>
							<ProfileIcon />
						</Box>
					}
				/>
			</BottomNavigation>
		</Paper>
	);
}

import { useState, useContext } from 'react';
import { Link as RouterLink, useNavigate, useLocation } from 'react-router-dom';
import { AppBar, Toolbar, Typography, Button, Box, Divider, Avatar, Menu, MenuItem, IconButton, Drawer, List, ListItemButton, ListItemText, Badge, useTheme } from '@mui/material';
import { useAuth } from '../context/AuthContext';
import { useNotifications } from '../hooks/useNotifications';
import { getOptimizedAvatar } from "../utils/image";
import { formatNotificationTime } from "../utils/dateUtils";
import { ColorModeContext } from '../App';
import { motion, AnimatePresence } from 'framer-motion';

const HamburgerIcon = () => (
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <line x1="3" y1="12" x2="21" y2="12"></line>
        <line x1="3" y1="6" x2="21" y2="6"></line>
        <line x1="3" y1="18" x2="21" y2="18"></line>
    </svg>
);

const BellIcon = () => (
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"></path>
        <path d="M13.73 21a2 2 0 0 1-3.46 0"></path>
    </svg>
);

const MoonIcon = () => (
	<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"></path></svg>
);

const SunIcon = () => (
	<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="5"></circle><line x1="12" y1="1" x2="12" y2="3"></line><line x1="12" y1="21" x2="12" y2="23"></line><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"></line><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"></line><line x1="1" y1="12" x2="3" y2="12"></line><line x1="21" y1="12" x2="23" y2="12"></line><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"></line><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"></line></svg>
);

export default function Navbar() {
    const theme = useTheme();
    const colorMode = useContext(ColorModeContext);
    const { user, logout } = useAuth();
    const { notifications, unreadCount, unreadMessages, markAsRead, markSingleAsRead, clearNotifications } = useNotifications();
    const navigate = useNavigate();
    const location = useLocation();
    const [anchorEl, setAnchorEl] = useState(null);
    const open = Boolean(anchorEl);
    const [notifAnchorEl, setNotifAnchorEl] = useState(null);
    const notifOpen = Boolean(notifAnchorEl);
    const [mobileOpen, setMobileOpen] = useState(false);
    
    const handleAvatarClick = (event) => setAnchorEl(event.currentTarget);
    const handleMenuClose = () => setAnchorEl(null);
    
    const handleNotifClick = (event) => {
        setNotifAnchorEl(event.currentTarget);
    };
    
    const handleNotifClose = () => setNotifAnchorEl(null);
    const handleDrawerToggle = () => setMobileOpen(!mobileOpen);
    
    const handleLogout = async () => {
        handleMenuClose();
        logout();
    };

    return (
        <>
				<AppBar
					position="sticky"
					elevation={0}
					sx={{ 
						borderBottom: "1px solid rgba(0,0,0,0.1)",
						backgroundColor: "primary.main",
					}}
				>
					<Toolbar sx={{ justifyContent: "space-between" }}>
						<Box
							sx={{
								display: "flex",
								alignItems: "center",
								gap: { xs: 1, md: 4 },
							}}
						>
							<IconButton
								color="inherit"
								edge="start"
								onClick={handleDrawerToggle}
								sx={{ display: { md: "none" } }}
								aria-label="Open navigation menu"
							>
								<HamburgerIcon />
							</IconButton>

							<Typography
								variant="h6"
								component={RouterLink}
								to="/"
								sx={{
									textDecoration: "none",
									color: "secondary.main",
									fontWeight: 900,
									fontSize: "1.1rem",
									letterSpacing: "-0.5px",
								}}
							>
								GMU Badminton
							</Typography>

							<Box
								sx={{
									display: { xs: "none", md: "flex" },
									gap: 1,
								}}
							>
								<Button
									color={location.pathname === "/" ? "secondary" : "inherit"}
									component={RouterLink}
									to="/"
									sx={{
										textTransform: "none",
										fontWeight: 600,
									}}
								>
									Dashboard
								</Button>
								<Button
									color={location.pathname === "/community" ? "secondary" : "inherit"}
									component={RouterLink}
									to="/community"
									sx={{
										textTransform: "none",
										fontWeight: 600,
									}}
								>
									Community
								</Button>
								<Button
									color={location.pathname === "/leaderboard" ? "secondary" : "inherit"}
									component={RouterLink}
									to="/leaderboard"
									sx={{
										textTransform: "none",
										fontWeight: 600,
									}}
								>
									Leaderboard
								</Button>
								<Button
									color={location.pathname === "/matchmaking" ? "secondary" : "inherit"}
									component={RouterLink}
									to="/matchmaking"
									sx={{
										textTransform: "none",
										fontWeight: 600,
									}}
								>
									Players
								</Button>
								<Button
									color={location.pathname === "/tournaments" ? "secondary" : "inherit"}
									component={RouterLink}
									to="/tournaments"
									sx={{
										textTransform: "none",
										fontWeight: 600,
									}}
								>
									Tournaments
								</Button>
								{user && user.role === "admin" && (
									<Button
										color="warning"
										variant="contained"
										component={RouterLink}
										to="/admin"
										sx={{
											textTransform: "none",
											fontWeight: "bold",
											ml: 2,
											boxShadow: "none",
										}}
									>
										Admin Panel
									</Button>
								)}
							</Box>
						</Box>

						<Box
							sx={{
								display: "flex",
								alignItems: "center",
								gap: 2,
							}}
						>
							<IconButton 
								onClick={colorMode.toggleColorMode} 
								color="inherit"
								aria-label="Toggle dark mode"
								sx={{
									transition: "all 0.2s",
									"&:hover": { color: "secondary.main", transform: "rotate(15deg)" },
								}}
							>
								{theme.palette.mode === 'dark' ? <SunIcon /> : <MoonIcon />}
							</IconButton>
							{user ? (
								<>
									<IconButton
										color="inherit"
										component={RouterLink}
										to="/messages"
										aria-label="View messages"
										sx={{
											transition: "all 0.2s",
											"&:hover": { color: "secondary.main" },
										}}
									>
										<Badge badgeContent={unreadMessages} color="error">
											<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z"></path></svg>
										</Badge>
									</IconButton>

									<IconButton
										color="inherit"
										onClick={handleNotifClick}
										aria-label="View notifications"
										sx={{
											transition: "all 0.2s",
											"&:hover": {
												color: "secondary.main",
											},
										}}
									>
										<Badge
											badgeContent={unreadCount}
											color="error"
										>
											<BellIcon />
										</Badge>
									</IconButton>

									<Menu
										anchorEl={notifAnchorEl}
										open={notifOpen}
										onClose={handleNotifClose}
										transformOrigin={{
											horizontal: "right",
											vertical: "top",
										}}
										anchorOrigin={{
											horizontal: "right",
											vertical: "bottom",
										}}
										slotProps={{
											paper: {
												elevation: 3,
												sx: {
													mt: 1.5,
													width: 320,
													borderRadius: 3,
													maxHeight: 400,
												},
											},
										}}
									>
										<Box
											sx={{
												px: 2,
												py: 1.5,
												display: "flex",
												justifyContent: "space-between",
												alignItems: "center",
												borderBottom: "1px solid #eee",
											}}
										>
											<Typography fontWeight="bold">
												Notifications
											</Typography>
											{notifications.length > 0 && (
												<Box sx={{ display: 'flex', gap: 2 }}>
													<Typography
														variant="caption"
														color="primary"
														sx={{ cursor: "pointer", fontWeight: "bold", "&:hover": { textDecoration: "underline" } }}
														onClick={markAsRead}
													>
														Mark all as read
													</Typography>
													<Typography
														variant="caption"
														color="error"
														sx={{ cursor: "pointer", fontWeight: "bold", "&:hover": { textDecoration: "underline" } }}
														onClick={clearNotifications}
													>
														Clear All
													</Typography>
												</Box>
											)}
										</Box>

										{notifications.length === 0 ? (
											<MenuItem
												sx={{
													py: 3,
													justifyContent: "center",
													color: "text.secondary",
												}}
												disableRipple
											>
												No new notifications
											</MenuItem>
										) : (
											notifications.map((notif, index) => (
												<motion.div
													key={notif._id || notif.id}
													initial={{ opacity: 0, x: 20 }}
													animate={{ opacity: 1, x: 0 }}
													transition={{ delay: index * 0.05 }}
												>
											<MenuItem
														component={RouterLink}
														to={notif.link}
														onClick={() => {
															handleNotifClose();
															if (!notif.read) markSingleAsRead(notif._id || notif.id);
														}}
														sx={{
															whiteSpace: "normal",
															py: 1.5,
															backgroundColor: notif.read ? "transparent" : "rgba(0, 102, 51, 0.05)",
															borderBottom: "1px solid #f5f5f5",
															"&:active": {
																transform: "scale(0.98)",
															},
															"&:hover": {
																backgroundColor: notif.read ? "rgba(0,0,0,0.02)" : "rgba(0, 102, 51, 0.1)",
															}
														}}
													>
														<Box>
														<Typography
															variant="body2"
															sx={{
																lineHeight: 1.3,
																fontWeight: notif.read ? "normal" : "bold"
															}}
														>
															{notif.message}
														</Typography>
														<Typography
															variant="caption"
															color="text.secondary"
															sx={{
																mt: 0.5,
																display:
																	"block",
															}}
														>
															{formatNotificationTime(notif.time)}
														</Typography>
													</Box>
												</MenuItem>
												</motion.div>
											))
										)}
									</Menu>

									<Avatar
										src={getOptimizedAvatar(user.profilePic, 40)}
										onClick={handleAvatarClick}
										sx={{
											width: 40,
											height: 40,
											bgcolor: "secondary.main",
											color: "primary.main",
											fontWeight: "bold",
											border: "2px solid #FFCC33",
											cursor: "pointer",
											transition: "transform 0.2s ease-in-out",
											"&:hover": { transform: "scale(1.08)" },
										}}
									>
										{!user.profilePic &&
											user.name?.charAt(0).toUpperCase()}
									</Avatar>

									<Menu
										anchorEl={anchorEl}
										open={open}
										onClose={handleMenuClose}
										transformOrigin={{
											horizontal: "right",
											vertical: "top",
										}}
										anchorOrigin={{
											horizontal: "right",
											vertical: "bottom",
										}}
										slotProps={{
											paper: {
												elevation: 3,
												sx: {
													mt: 1.5,
													minWidth: 150,
													borderRadius: 2,
												},
											},
										}}
									>
										<MenuItem
											component={RouterLink}
											to={`/profile/${user.id}`}
											onClick={(e) => {
												if (e.currentTarget)
													e.currentTarget.blur();
												handleMenuClose();
											}}
											sx={{ fontWeight: "bold" }}
										>
											View Profile
										</MenuItem>
										<Divider />
										<MenuItem
											onClick={(e) => {
												if (e.currentTarget)
													e.currentTarget.blur();
												handleLogout();
											}}
											sx={{
												color: "error.main",
												fontWeight: "bold",
											}}
										>
											Log Out
										</MenuItem>
									</Menu>
								</>
							) : (
								<Button
									color="inherit"
									variant="outlined"
									component={RouterLink}
									to="/auth"
									sx={{
										borderColor: "rgba(255,255,255,0.4)",
										textTransform: "none",
										fontWeight: "bold",
									}}
								>
									Login
								</Button>
							)}
						</Box>
					</Toolbar>
				</AppBar>

				<Drawer
					anchor="left"
					open={mobileOpen}
					onClose={handleDrawerToggle}
					sx={{
						display: { xs: "block", md: "none" },
						"& .MuiDrawer-paper": {
							boxSizing: "border-box",
							width: 250,
							backgroundColor: "#006633",
							color: "white",
						},
					}}
				>
					<Box
						onClick={handleDrawerToggle}
						sx={{ textAlign: "center", py: 3 }}
					>
						<Typography
							variant="h6"
							sx={{ fontWeight: 900, color: "#FFCC33" }}
						>
							GMU Badminton
