					fullWidth
					size="small"
					multiline
					maxRows={4}
					placeholder={
						currentUser ? "Write a comment..." : "Login to comment"
					}
					value={newReplyText}
					onChange={handleTyping}
					onKeyDown={(e) => {
						if (e.key === "Enter" && !e.shiftKey) {
							e.preventDefault();
							handlePostMainComment();
						}
					}}
					disabled={!currentUser}
					sx={{
						"& .MuiOutlinedInput-root": {
							borderRadius: "20px",
							backgroundColor: "action.hover",
							py: 1,
							px: 2,
