								position: "absolute",
								bottom: -8,
								right: -8,
								bgcolor: "background.paper",
								borderRadius: 10,
								px: 0.6,
								py: 0.2,
								display: "flex",
								alignItems: "center",
								gap: 0.5,
								boxShadow: "0 1px 4px rgba(0,0,0,0.15)",
								cursor: "pointer",
								"&:active": { transform: "scale(0.95)" },
							}}
						>
							<Avatar
								sx={{
									width: 14,
									height: 14,
									bgcolor: "primary.main",
									fontSize: "0.5rem",
								}}
							>
								👍
							</Avatar>
							<Typography
								variant="caption"
								sx={{
									fontSize: "0.7rem",
									color: "text.secondary",
									fontWeight: "bold",
								}}
							>
								{reply.likedBy.length}
							</Typography>
						</Box>
					)}
				</Box>

				<Menu
					anchorEl={menuAnchor}
					open={Boolean(menuAnchor)}
					onClose={closeMenu}
					slotProps={{
						paper: { elevation: 2, sx: { borderRadius: 2 } },
					}}
				>
					{currentUser?.id === reply.authorId && (
						<MenuItem
							onClick={() => {
								setIsEditing(true);
								closeMenu();
							}}
							sx={{ fontSize: "0.875rem", fontWeight: "bold" }}
						>
							✎ Edit
						</MenuItem>
					)}
					<MenuItem
						onClick={() => {
							promptDelete();
							closeMenu();
						}}
						sx={{
							fontSize: "0.875rem",
							color: "error.main",
							fontWeight: "bold",
						}}
					>
						🗑 Delete
					</MenuItem>
				</Menu>

				<Box sx={{ display: "flex", gap: 2, ml: 1, mt: 0.5 }}>
					<Typography
						variant="caption"
						onClick={() =>
							handleToggleLike(
								`/api/forum/${localPostId}/comments/${commentId}/replies/${reply._id}/like`,
								reply._id,
							)
						}
						sx={{
							cursor: "pointer",
							fontWeight: "bold",
							color: reply.likedBy?.includes(currentUser?.id)
								? "primary.main"
								: "text.secondary",
							"&:active": { transform: "scale(0.9)" },
						}}
					>
						Like
					</Typography>
					<Typography
						variant="caption"
						onClick={onReply}
						sx={{
							cursor: "pointer",
							fontWeight: "bold",
							color: "text.secondary",
							"&:active": { transform: "scale(0.9)" },
						}}
					>
						Reply
					</Typography>
					{/* Fixed: Adding timestamp back in for replies */}
					<Typography variant="caption" color="text.disabled">
						{formatTime(reply.timestamp)}
					</Typography>
				</Box>
			</Box>
		</Box>
	);
}

import React, { useState, useRef } from "react";
import ReactCrop, { centerCrop, makeAspectCrop } from "react-image-crop";
import "react-image-crop/dist/ReactCrop.css";
import {
	Dialog,
	DialogTitle,
	DialogContent,
	DialogActions,
	Button,
	Box,
} from "@mui/material";
import getCroppedImg from "../../utils/cropImage";

function centerAspectCrop(mediaWidth, mediaHeight, aspect) {
	return centerCrop(
		makeAspectCrop(
			{
				unit: "%",
				width: 90,
			},
			aspect,
			mediaWidth,
			mediaHeight
		),
		mediaWidth,
		mediaHeight
	);
}

export default function ImageCropModal({
	open,
	imageSrc,
	onClose,
	onCropComplete,
	aspectRatio,
	title = "Crop Image"
}) {
	const [crop, setCrop] = useState();
	const [completedCrop, setCompletedCrop] = useState(null);
	const imgRef = useRef(null);

	const onImageLoad = (e) => {
		const { width, height } = e.currentTarget;
		if (aspectRatio) {
			setCrop(centerAspectCrop(width, height, aspectRatio));
		}
	};

	const handleSave = async () => {
		if (!completedCrop || !imgRef.current) return;

		const image = imgRef.current;
		const scaleX = image.naturalWidth / image.width;
		const scaleY = image.naturalHeight / image.height;

		const pixelCrop = {
			x: completedCrop.x * scaleX,
			y: completedCrop.y * scaleY,
			width: completedCrop.width * scaleX,
			height: completedCrop.height * scaleY,
		};

		try {
			const croppedImageBlob = await getCroppedImg(imageSrc, pixelCrop);
			onCropComplete(croppedImageBlob);
		} catch (e) {
			console.error(e);
		}
	};

	return (
		<Dialog 
			open={open} 
			onClose={onClose} 
			maxWidth="md" 
			fullWidth
			PaperProps={{
				sx: {
					bgcolor: 'background.paper',
					borderRadius: 4,
					overflow: 'hidden'
				}
			}}
		>
			<DialogTitle sx={{ fontWeight: "900", textAlign: "center", py: 3 }}>
				{title}
			</DialogTitle>
			<DialogContent sx={{ 
				display: "flex", 
				justifyContent: "center", 
				alignItems: "center", 
				bgcolor: "background.default", 
				minHeight: 400,
				p: 0,
				position: "relative"
			}}>
				{imageSrc && (
					<ReactCrop
						crop={crop}
						onChange={(_, percentCrop) => setCrop(percentCrop)}
						onComplete={(c) => setCompletedCrop(c)}
						aspect={aspectRatio}
						ruleOfThirds
						style={{ maxWidth: '100%', maxHeight: '60vh' }}
					>
						<img
							ref={imgRef}
							src={imageSrc}
							onLoad={onImageLoad}
							style={{ maxHeight: "60vh", maxWidth: "100%", display: "block", objectFit: "contain" }}
							alt="Crop"
						/>
					</ReactCrop>
				)}
			</DialogContent>
			<DialogActions sx={{ p: 3, display: "flex", justifyContent: "space-between", bgcolor: "background.paper" }}>
				<Button 
					onClick={onClose} 
					sx={{ 
						borderRadius: 3, 
						textTransform: "none",
						fontWeight: "bold",
						color: "text.secondary",
						px: 3
					}}
				>
					Cancel
				</Button>
				<Button 
					onClick={handleSave} 
					variant="contained" 
					color="primary" 
					sx={{ 
						borderRadius: 3, 
						textTransform: "none", 
						fontWeight: "bold",
						px: 4,
						py: 1
					}}
					disabled={!completedCrop?.width || !completedCrop?.height}
				>
					Save Photo
				</Button>
			</DialogActions>
		</Dialog>
	);
}

