								bgcolor: status?.includes('CLOSED') ? 'rgba(255,68,68,0.2)' : status?.includes('Active') ? 'rgba(255,204,51,0.2)' : 'rgba(0,230,118,0.2)', 
								color: status?.includes('CLOSED') ? '#FF4444' : status?.includes('Active') ? '#FFCC33' : '#00E676', 
								fontWeight: 'bold' 
