				</Box>
			</Paper>

			<Grid container spacing={{ xs: 2, sm: 3, md: 4 }}>
				<Grid size={{'xs': 12, 'md': 4}}>
					<Box
						sx={{
							display: "flex",
							alignItems: "center",
							gap: 1,
							mb: 2,
						}}
					>
						<Box
							sx={{
								color: "secondary.main",
								display: "flex",
								alignItems: "center",
							}}
						>
							<MegaphoneIcon />
						</Box>
						<Typography
							variant="h5"
							fontWeight="900"
							color="primary"
						>
							Official Updates
						</Typography>
					</Box>

					{currentUser?.role === "admin" && (
						<Paper
							elevation={0}
							sx={{
								p: 2,
								mb: 2,
								borderRadius: 3,
								border: "1px solid #006633",
								backgroundColor: "rgba(0,102,51,0.02)",
							}}
						>
							<Typography
								variant="caption"
								fontWeight="bold"
								color="primary"
								sx={{ mb: 1, display: "block" }}
							>
								👑 Admin Broadcast
							</Typography>
							<TextField
								fullWidth
								multiline
								maxRows={4}
								placeholder="Share news, cancellations, or updates..."
								value={newUpdateText}
								onChange={(e) =>
									setNewUpdateText(e.target.value)
								}
								size="small"
								sx={{
									mb: 1.5,
									"& .MuiOutlinedInput-root": {
										borderRadius: 2,
										backgroundColor: "background.paper",
									},
								}}
							/>
							<Button
								variant="contained"
								color="primary"
								fullWidth
								disabled={!newUpdateText.trim() || isPosting}
								onClick={handlePostUpdate}
								sx={{
									fontWeight: "bold",
									borderRadius: 2,
									textTransform: "none",
								}}
							>
								{isPosting
									? "Broadcasting..."
									: "Post Official Update"}
							</Button>
						</Paper>
					)}

					<Paper
						elevation={0}
						className="custom-scrollbar"
						sx={{
							border: "1px solid", borderColor: "divider",
							borderRadius: 4,
							maxHeight: { xs: "350px", md: "600px" },
							overflowY: "auto",
							overflowX: "hidden",
							backgroundColor: "background.paper",
							display: "flex",
							flexDirection: "column",
							width: "100%", // Force 100% width on the container
						}}
					>
						{loading ? (
							<Box
								sx={{
									display: "flex",
									justifyContent: "center",
									p: 4,
								}}
							>
								<CircularProgress />
							</Box>
						) : announcements.length === 0 ? (
							<Box
								sx={{
									display: "flex",
									flexDirection: "column",
									alignItems: "center",
									p: 4,
									textAlign: "center",
									opacity: 0.5,
									width: "100%",
								}}
							>
								<style>
									{`
										@keyframes floatMsg { 0% { transform: translateY(0px); } 50% { transform: translateY(-10px); } 100% { transform: translateY(0px); } }
