											<Typography
												variant="body1"
												sx={{
													whiteSpace: "pre-wrap",
													wordBreak: "break-word",
													overflowWrap: "anywhere",
													lineHeight: 1.6,
													color: "text.primary",
													width: "100%",
													display: "block",
