						)}
					</Paper>
				</Grid>

				<Grid size={{'xs': 12, 'md': 8}}>
					<Typography
						variant="h5"
						fontWeight="900"
						color="primary"
						sx={{ mb: 2 }}
					>
						Live RAC Court Status
					</Typography>
					<Box
						sx={{
							display: "flex",
							flexDirection: "column",
							gap: 2.5,
						}}
					>
						{loading ? (
							[1, 2, 3].map((n) => (
								<Paper
									key={n}
									elevation={0}
									sx={{
										p: 3,
										borderRadius: 3,
										border: "1px solid", borderColor: "divider",
										display: 'flex',
										gap: 2
									}}
								>
									<Skeleton variant="rounded" width={80} height={80} />
									<Box sx={{ flexGrow: 1 }}>
										<Skeleton variant="text" sx={{ fontSize: '1.5rem' }} width="40%" />
										<Skeleton variant="text" sx={{ fontSize: '1rem' }} width="20%" />
									</Box>
								</Paper>
							))
						) : schedule?.timeSlots?.length > 0 ? (
							schedule.timeSlots.map((slot, index) => {
								const getStatusColor = (status) => {
									switch(status) {
										case 'DEDICATED': return 'success.main';
										case 'CLUB_ONLY': return 'info.main';
										case 'OPEN_REQ': return 'warning.main';
										case 'UNAVAILABLE': return 'error.main';
										default: return 'text.secondary';
									}
								};
								
								const getStatusLabel = (status) => {
									switch(status) {
										case 'DEDICATED': return '🟢 Dedicated Drop-in';
										case 'CLUB_ONLY': return '🔵 Club Members Only';
										case 'OPEN_REQ': return '🟡 Open Rec (Ask for Nets)';
										case 'UNAVAILABLE': return '🔴 Unavailable';
										default: return status;
									}
								};

								const startTimeObj = new Date(slot.startTime);
								const startTime = startTimeObj.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
								const endTime = new Date(slot.endTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
								const dayName = startTimeObj.toLocaleDateString('en-US', { weekday: 'short' });

								return (
									<Paper
										key={index}
										elevation={0}
										sx={{
											display: "flex",
											borderRadius: 4,
											overflow: "hidden",
											border: "1px solid", borderColor: "divider",
											transition: "all 0.2s",
											"&:hover": {
												borderColor: "primary.main",
												boxShadow: "0 4px 15px rgba(0,0,0,0.05)",
											},
										}}
									>
										<Box
											sx={{
												bgcolor: getStatusColor(slot.status),
												color: "white",
												minWidth: { xs: 80, sm: 100 },
												display: "flex",
												flexDirection: "column",
												justifyContent: "center",
												alignItems: "center",
												p: 2,
												textAlign: "center"
											}}
										>
											<Typography variant="caption" fontWeight="bold" sx={{ textTransform: 'uppercase', letterSpacing: '1px', mb: 0.5, opacity: 0.9 }}>
												{dayName}
											</Typography>
											<Typography variant="body2" fontWeight="bold">
												{startTime}
											</Typography>
											<Typography variant="caption" sx={{ opacity: 0.8 }}>
												to
											</Typography>
											<Typography variant="body2" fontWeight="bold">
												{endTime}
											</Typography>
										</Box>
										<Box
											sx={{
												p: { xs: 2, sm: 3 },
												flexGrow: 1,
												display: "flex",
												flexDirection: "column",
												justifyContent: "center",
											}}
										>
											<Box
												sx={{
													display: "flex",
													justifyContent: "space-between",
													alignItems: "flex-start",
													mb: 1,
												}}
											>
												<Typography variant="h6" fontWeight="bold">
													{slot.eventName}
												</Typography>
												<Chip
													label={getStatusLabel(slot.status)}
													size="small"
													sx={{
														fontWeight: "bold",
														borderRadius: 2,
														bgcolor: `${getStatusColor(slot.status)}22`,
														color: getStatusColor(slot.status),
														border: `1px solid ${getStatusColor(slot.status)}`
													}}
												/>
											</Box>
											<Box
												sx={{
													display: "flex",
													flexWrap: "wrap",
													gap: { xs: 1.5, sm: 3 },
													color: "text.secondary",
													mt: 0.5,
												}}
											>
												<Typography
													variant="body2"
													sx={{
														display: "flex",
														alignItems: "center",
														gap: 0.5,
														color: "text.secondary",
													}}
												>
													<PinIcon /> {schedule.facilityName}
												</Typography>
											</Box>
										</Box>
									</Paper>
								);
							})
						) : (
							<Paper
								elevation={0}
								sx={{
									p: 4,
									borderRadius: 3,
									border: "1px solid", borderColor: "divider",
									textAlign: "center",
								}}
							>
								<Typography color="text.secondary">
									No live court schedule available right now.
								</Typography>
							</Paper>
						)}
					</Box>
				</Grid>
			</Grid>

			

			<Dialog
				open={!!deleteUpdateId}
				onClose={() => setDeleteUpdateId(null)}
				PaperProps={{ sx: { borderRadius: 3, p: 1 } }}
			>
				<DialogTitle
					sx={{
						fontWeight: "bold",
						display: "flex",
						alignItems: "center",
						gap: 1,
						color: "error.main",
					}}
				>
					<TrashIconLarge /> Confirm Deletion
				</DialogTitle>
				<DialogContent>
					<Typography>
						Are you sure you want to permanently delete this
						official announcement? This action cannot be undone.
					</Typography>
				</DialogContent>
				<MuiDialogActions sx={{ px: 3, pb: 2 }}>
					<Button
						onClick={() => setDeleteUpdateId(null)}
						color="inherit"
						sx={{ fontWeight: "bold", textTransform: "none" }}
					>
						Cancel
					</Button>
					<Button
						onClick={confirmDeleteUpdate}
						variant="contained"
						color="error"
						sx={{
							fontWeight: "bold",
							textTransform: "none",
							borderRadius: 2,
						}}
					>
						Delete
					</Button>
				</MuiDialogActions>
			</Dialog>
		</Box>
	);
}

import React, { useState, useEffect, useRef, useCallback } from "react";
import apiFetch from "../utils/api";
import { useAuth } from "../context/AuthContext";
import { toast } from "react-hot-toast";
import {
	Typography, Box, Paper, Chip, Fab, Dialog, DialogTitle,
	DialogContent, DialogActions, TextField, useTheme, useMediaQuery,
	Skeleton, CircularProgress, Avatar, Tabs, Tab, Button, Select, MenuItem, FormControl, InputLabel
} from "@mui/material";
import PostCard from "../components/PostCard";
import socket from "../utils/socket";
import { useNavigate } from "react-router-dom";

export default function Forum() {
	const { user: currentUser } = useAuth();
	const theme = useTheme();
	const fullScreen = useMediaQuery(theme.breakpoints.down("md"));

	const [tab, setTab] = useState("foryou"); // "foryou", "top", "latest"
	const [selectedTag, setSelectedTag] = useState("");
	const [feed, setFeed] = useState([]);
	const [newPostsQueue, setNewPostsQueue] = useState([]);
	const [bookmarkedPosts, setBookmarkedPosts] = useState(new Set());
	const [page, setPage] = useState(1);
	const [hasMore, setHasMore] = useState(true);
	const [isLoading, setIsLoading] = useState(true);
	const [isFetchingMore, setIsFetchingMore] = useState(false);
	const observer = useRef();

	const [isModalOpen, setIsModalOpen] = useState(false);
	const [newPost, setNewPost] = useState({ title: "", content: "", imageUrl: "", tags: [] });
	const [postImages, setPostImages] = useState([]);
	const [isUploadingImage, setIsUploadingImage] = useState(false);
	const isFormValid = newPost.title.length > 0 && newPost.content.length > 0;

	const formatTime = (dateString) => {
		if (!dateString) return "";
		return new Date(dateString).toLocaleDateString("en-US", {
			month: "short", day: "numeric", hour: "numeric", minute: "2-digit",
		});
	};

	const lastFeedElementRef = useCallback(node => {
		if (isLoading || isFetchingMore) return;
		if (observer.current) observer.current.disconnect();
		observer.current = new IntersectionObserver(entries => {
			if (entries[0].isIntersecting && hasMore) {
				setPage(prevPage => prevPage + 1);
			}
		});
		if (node) observer.current.observe(node);
	}, [isLoading, isFetchingMore, hasMore]);

	const cursorRef = useRef(null);
	const sessionTimeRef = useRef(null);

	useEffect(() => {
		const fetchFeed = async () => {
			const isFirstPage = page === 1;
			if (isFirstPage) {
				setIsLoading(true);
				cursorRef.current = null;
				// If refresh is manually triggered without tab change, update session time
				if (page === 1 && !cursorRef.current) sessionTimeRef.current = Date.now();
			} else {
				setIsFetchingMore(true);
			}

			try {
				const tagQuery = selectedTag ? `&tag=${encodeURIComponent(selectedTag)}` : "";
				const cursorQuery = cursorRef.current ? `&cursor=${cursorRef.current}` : "";
				const sessionQuery = `&sessionTime=${sessionTimeRef.current}`;
				const res = await apiFetch(`/api/feed?tab=${tab}&limit=10${tagQuery}${cursorQuery}${sessionQuery}`);
				if (res.ok) {
					const data = await res.json();
					cursorRef.current = data.nextCursor;
					setHasMore(!!data.nextCursor);
					if (data.bookmarkedPosts) setBookmarkedPosts(new Set(data.bookmarkedPosts));
					
					if (isFirstPage) {
						setFeed(data.feed);
					} else {
						setFeed(prev => {
							const existingIds = new Set(prev.map(item => item._id));
							const newItems = data.feed.filter(item => !existingIds.has(item._id));
							return [...prev, ...newItems];
						});
					}
				}
			} catch (e) {
				console.error("Failed to load community feed", e);
			} finally {
				setIsLoading(false);
				setIsFetchingMore(false);
			}
		};
		fetchFeed();
	}, [tab, page, selectedTag]);

	// Listen for real-time updates
	useEffect(() => {
		const handleNewPost = (post) => {
			if (!post || !post._id) return;
			setFeed(prev => {
				if (prev.find(p => p._id === post._id || p.referenceId === post._id)) return prev;
				setNewPostsQueue(q => {
					if (q.find(p => p._id === post._id || p.referenceId === post._id)) return q;
					return [post, ...q];
				});
				return prev;
			});
		};

		const handlePostUpdated = (updatedPost) => {
			// Update likes/comments inline without changing the array order!
			setFeed(prevFeed => prevFeed.map(item => {
				if (item.type === 'post' && item.referenceId === updatedPost._id) {
					const totalComments = updatedPost.comments?.reduce((acc, c) => acc + 1 + (c.replies?.length || 0), 0) || 0;
					return {
						...item,
						likes: updatedPost.likedBy?.length || 0,
						comments: totalComments
					};
				}
				return item;
			}));
		};

		socket.on("postCreated", handleNewPost);
		socket.on("matchConfirmed", handleNewPost);
		socket.on("postUpdated", handlePostUpdated); // For likes/comments

		return () => {
			socket.off("postCreated", handleNewPost);
			socket.off("matchConfirmed", handleNewPost);
			socket.off("postUpdated", handlePostUpdated);
		};
	}, []);

	const handleTabChange = (event, newValue) => {
		setTab(newValue);
		setPage(1);
		setFeed([]);
	};

	const handleSubmit = async () => {
		if (!currentUser) return alert("You must be logged in to post!");
		try {
			setIsUploadingImage(true);
			let finalImageUrls = [];

			if (postImages.length > 0) {
				const formData = new FormData();
				postImages.forEach(file => formData.append("images", file));
				formData.append("type", "postAttachment");
				formData.append("userId", currentUser.id);

				const uploadRes = await apiFetch("/api/upload/images", { method: "POST", body: formData });
				const uploadData = await uploadRes.json();
				if (uploadRes.ok) finalImageUrls = uploadData.imageUrls;
				else {
					setIsUploadingImage(false);
					return toast.error("Failed to upload image. " + uploadData.message);
				}
			}

			// Submit Post (using old Forum API but it creates an ActivityFeed under the hood)
			// Target date is no longer strictly used for filtering, but backend requires it.
			const res = await apiFetch("/api/forum", {
				method: "POST",
				body: JSON.stringify({
					title: newPost.title,
					content: newPost.content,
					imageUrl: finalImageUrls[0] || "",
					imageUrls: finalImageUrls,
					authorName: currentUser.name,
					authorId: currentUser.id,
                    tags: newPost.tags,
					targetDate: new Date().toLocaleDateString("en-US", { month: "short", day: "numeric" }),
				}),
			});

			const data = await res.json();
			setIsUploadingImage(false);
			if (!res.ok) return toast.error(data.message || "Failed to post. Please try again.");

			setNewPost({ title: "", content: "", imageUrl: "", tags: [], visibility: 'PUBLIC' });
			setPostImages([]);
			setIsModalOpen(false);
			toast.success("Post created successfully!");
		} catch (error) {
			setIsUploadingImage(false);
			console.error("Failed to post", error);
		}
	};

	return (
		<Box sx={{ pb: 10 }}>
			{/* HERO BANNER */}
			<Box 
				sx={{ 
					width: '100%', mb: 4, py: { xs: 4, md: 6 },
					background: "linear-gradient(135deg, rgba(0, 102, 51, 0.9) 0%, rgba(255, 204, 51, 0.8) 100%)",
					borderRadius: 4,
					position: 'relative', overflow: 'hidden',
					display: 'flex', flexDirection: 'column',
					alignItems: 'center', justifyContent: 'center',
					boxShadow: '0 4px 30px rgba(0, 0, 0, 0.1)',
				}}
			>
				<Typography variant="h3" fontWeight="900" color="white" align="center" sx={{ textShadow: "0px 2px 4px rgba(0,0,0,0.5)", zIndex: 1, mb: 2 }}>
					Community Hub
				</Typography>
				<Typography variant="h6" color="rgba(255,255,255,0.9)" align="center" sx={{ zIndex: 1, px: 2 }}>
					Connect, discuss, and track all the action happening on campus.
				</Typography>
			</Box>

			{/* TABS NAVIGATION */}
			<Box sx={{ width: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center', mb: 4, gap: 2 }}>
				<Tabs value={tab} onChange={handleTabChange} textColor="primary" indicatorColor="primary" 
					sx={{ 
						'& .MuiTab-root': { fontWeight: 'bold', fontSize: '1.1rem', textTransform: 'none', px: { xs: 2, sm: 4 } },
						background: 'background.paper', borderRadius: 10, boxShadow: 1, p: 0.5
					}}>
					<Tab label="For You" value="foryou" />
					<Tab label="Trending" value="top" />
					<Tab label="Latest" value="latest" />
				</Tabs>

				{/* ACTION BAR (TRENDING TAGS + REFRESH) */}
				<Box 
					sx={{ 
						width: '100%', maxWidth: '800px', display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 1, gap: 2
					}}
				>
                    <Box 
                        sx={{ 
                            display: 'flex', gap: 1, overflowX: 'auto', pb: 1, flex: 1,
                            '&::-webkit-scrollbar': { display: 'none' }, // Hide scrollbar for clean UI
                            msOverflowStyle: 'none', scrollbarWidth: 'none' 
                        }}
                    >
                        <Chip label="Trending" size="small" sx={{ fontWeight: 'bold', background: 'linear-gradient(45deg, #FF512F 0%, #F09819 100%)', color: 'white' }} />
                        {['Tournament', 'RAC', 'Stringing', 'Doubles', 'Equipment'].map((tag) => (
                            <Chip 
                                key={tag} 
                                label={tag} 
                                size="small" 
                                variant={selectedTag === tag ? "filled" : "outlined"}
                                color={selectedTag === tag ? "primary" : "default"}
                                onClick={() => {
                                    setSelectedTag(selectedTag === tag ? "" : tag);
                                    setPage(1);
                                }}
                                sx={{ 
                                    fontWeight: 'bold', cursor: 'pointer', 
                                    '&:hover': { bgcolor: 'primary.main', color: 'white', borderColor: 'primary.main' } 
                                }} 
                            />
                        ))}
                    </Box>

                    <Button 
                        variant="outlined" 
                        size="small" 
                        color="inherit"
                        onClick={() => { setPage(1); setFeed([]); }}
                        sx={{ minWidth: 'auto', borderRadius: 2, display: 'flex', gap: 1, fontWeight: 'bold', height: 26 }}
                    >
                        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21.5 2v6h-6M2.13 15.57a9 9 0 1 0 3.12-11.83l-4.75 4.76"/></svg>
                        <Box sx={{ display: { xs: 'none', sm: 'block' } }}>Refresh</Box>
                    </Button>
				</Box>

			</Box>

			<Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4, width: '100%', maxWidth: '680px', mx: 'auto' }}>
				{/* FACEBOOK STYLE COMPOSER */}
				<Paper 
					elevation={1} 
					sx={{ 
						p: 2, 
						width: '100%', 
						borderRadius: 4, 
						display: 'flex', 
						alignItems: 'center', 
						gap: 2,
						mb: -2 
					}}
				>
					<Avatar src={currentUser?.avatarUrl} alt={currentUser?.name} />
					<Box 
						onClick={() => setIsModalOpen(true)}
						sx={{ 
							flex: 1, 
							backgroundColor: 'action.hover', 
							borderRadius: 10, 
							py: 1.5, 
							px: 3, 
							cursor: 'pointer',
							'&:hover': { backgroundColor: 'action.selected' }
						}}
					>
						<Typography color="text.secondary" sx={{ fontSize: '0.95rem' }}>
							What's on your mind{currentUser?.name ? `, ${currentUser.name.split(' ')[0]}` : ''}?
						</Typography>
					</Box>
				</Paper>

				{/* NEW POSTS PILL */}
				{newPostsQueue.length > 0 && (
					<Box 
						onClick={() => {
							setFeed(prev => [...newPostsQueue, ...prev]);
							setNewPostsQueue([]);
							window.scrollTo({ top: 0, behavior: 'smooth' });
						}}
						sx={{
							position: 'sticky',
							top: 80,
							zIndex: 10,
							backgroundColor: 'primary.main',
							color: 'primary.contrastText',
							px: 3,
							py: 1,
							borderRadius: 10,
							cursor: 'pointer',
							boxShadow: 3,
							display: 'flex',
							alignItems: 'center',
							gap: 1,
							transition: 'transform 0.2s',
							'&:hover': { transform: 'scale(1.05)' }
						}}
					>
						<Typography variant="body2" sx={{ fontWeight: 'bold' }}>
							↑ {newPostsQueue.length} New Post{newPostsQueue.length > 1 ? 's' : ''}
						</Typography>
					</Box>
				)}

				{/* FEED */}
				{isLoading ? (
					[1, 2, 3, 4].map(n => (
						<Paper key={n} elevation={0} sx={{ p: 3, borderRadius: 4, border: "1px solid", borderColor: "divider", mb: 2, width: '100%' }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                                <Skeleton variant="circular" width={40} height={40} />
                                <Box sx={{ ml: 2, width: '100%' }}>
                                    <Skeleton variant="text" width="60%" height={24} />
                                    <Skeleton variant="text" width="40%" height={20} />
                                </Box>
                            </Box>
                            <Skeleton variant="rounded" height={100} sx={{ borderRadius: 2 }} />
                        </Paper>
					))
				) : feed.length === 0 ? (
					<Box sx={{ width: '100%', display: 'flex', justifyContent: 'center', p: 4 }}>
						<Typography color="text.secondary">No activity found.</Typography>
					</Box>
				) : (
					feed.map((item, idx) => {
						if (item.type === 'post') {
							// Transform ActivityFeed back to Post format for PostCard component
							const mockPost = {
								_id: item.referenceId,
								title: item.title,
								content: item.content,
								imageUrl: item.image,
								imageUrls: item.images || [],
								authorId: item.authorId,
								authorName: item.authorName,
								authorBadges: item.authorBadges,
								timestamp: item.createdAt,
                                tags: item.tags || [],
								likedBy: new Array(Math.max(0, item.likes || 0)).fill('mock_id'), // PostCard only cares about length
								recentLikerAvatars: item.recentLikerAvatars || [],
																comments: new Array(Math.max(0, item.comments || 0)).fill({}), 
							};
							return (
								<Box key={item._id} ref={idx === feed.length - 1 ? lastFeedElementRef : null} sx={{ width: '100%' }}>
									<PostCard post={mockPost} currentUser={currentUser} isBookmarked={bookmarkedPosts.has(item.referenceId)} onBookmarkToggle={(isBookmarked) => setBookmarkedPosts(prev => { const n = new Set(prev); if(isBookmarked) n.add(item.referenceId); else n.delete(item.referenceId); return n; })} onDelete={() => {}} />
								</Box>
							);
						}
						
						if (item.type === 'match') {
							const team1Wins = item.team1Score > item.team2Score;
							const team2Wins = item.team2Score > item.team1Score;

							return (
								<Box key={item._id} ref={idx === feed.length - 1 ? lastFeedElementRef : null} sx={{ width: '100%' }}>
									<Paper 
										elevation={0} 
										sx={{ 
											p: 0, borderRadius: 4, overflow: 'hidden', border: "1px solid", borderColor: "divider", 
											display: 'flex', flexDirection: 'column',
											background: 'linear-gradient(135deg, rgba(0, 102, 51, 0.05) 0%, rgba(255, 204, 51, 0.05) 100%)',
											transition: '0.3s cubic-bezier(0.16, 1, 0.3, 1)',
											'&:hover': {
												transform: 'scale(1.02) translateY(-4px)',
												boxShadow: '0 12px 30px rgba(0,102,51,0.15)',
												borderColor: 'primary.main'
											}
										}}
									>
										{/* HEADER BAR */}
										<Box sx={{ display: 'flex', px: 3, py: 1.5, background: 'rgba(0,0,0,0.03)', borderBottom: '1px solid rgba(0,0,0,0.05)', alignItems: 'center' }}>
											<Chip label="🏆 Official Match" size="small" sx={{ fontWeight: 'bold', background: 'linear-gradient(45deg, #FFD700 0%, #FFA500 100%)', color: 'black' }} />
											<Typography variant="caption" fontWeight="bold" color="text.secondary" ml="auto">{formatTime(item.createdAt)}</Typography>
										</Box>

										{/* SCOREBOARD */}
										<Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', p: 3, position: 'relative' }}>
											{/* TEAM 1 */}
											<Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 1.5, width: '35%', position: 'relative' }}>
												{team1Wins && <Box sx={{ position: 'absolute', top: -20, fontSize: '1.5rem',  }}>👑</Box>}
												<Box sx={{ display: 'flex' }}>
													{item.team1Avatars?.map((avatar, i) => (
														<Avatar key={i} src={avatar} sx={{ width: 56, height: 56, ml: i > 0 ? -2 : 0, border: '3px solid', borderColor: team1Wins ? '#FFD700' : 'background.paper', zIndex: 2 - i, boxShadow: 2 }} />
													))}
												</Box>
												<Typography variant="body2" fontWeight="900" textAlign="center" sx={{ width: '100%', wordWrap: 'break-word', lineHeight: 1.2 }}>
													{item.team1?.map(name => name.split(' ')[0]).join(' & ')}
												</Typography>
											</Box>

											{/* HUGE SCORE */}
											<Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', width: '30%' }}>
												<Typography variant="overline" color="text.secondary" fontWeight="bold" sx={{ mb: -1 }}>FINAL</Typography>
												<Typography variant="h3" fontWeight="900" sx={{ letterSpacing: '-2px', color: 'text.primary' }}>
													<span style={{ color: team1Wins ? '#006633' : 'inherit' }}>{item.team1Score}</span>
													<span style={{ margin: '0 8px', color: '#ccc' }}>-</span>
													<span style={{ color: team2Wins ? '#006633' : 'inherit' }}>{item.team2Score}</span>
												</Typography>
											</Box>

											{/* TEAM 2 */}
											<Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 1.5, width: '35%', position: 'relative' }}>
												{team2Wins && <Box sx={{ position: 'absolute', top: -20, fontSize: '1.5rem',  }}>👑</Box>}
												<Box sx={{ display: 'flex' }}>
													{item.team2Avatars?.map((avatar, i) => (
														<Avatar key={i} src={avatar} sx={{ width: 56, height: 56, ml: i > 0 ? -2 : 0, border: '3px solid', borderColor: team2Wins ? '#FFD700' : 'background.paper', zIndex: 2 - i, boxShadow: 2 }} />
													))}
												</Box>
												<Typography variant="body2" fontWeight="900" textAlign="center" sx={{ width: '100%', wordWrap: 'break-word', lineHeight: 1.2 }}>
													{item.team2?.map(name => name.split(' ')[0]).join(' & ')}
												</Typography>
											</Box>
										</Box>
									</Paper>
								</Box>
							);
						}
						
						return null;
					})
				)}
			</Box>
			
			<Box sx={{ display: 'flex', justifyContent: 'center', mt: 4, height: 60, alignItems: 'center' }}>
				{isFetchingMore && <CircularProgress size={24} color="primary" />}
                {!isFetchingMore && !hasMore && feed.length > 0 && (
                    <Typography variant="body2" color="text.secondary" sx={{ fontWeight: 'bold' }}>
                        You're all caught up! 🏸
                    </Typography>
                )}
			</Box>

			{/* Create Post Modal */}
			<Dialog fullScreen={fullScreen} open={isModalOpen} onClose={() => setIsModalOpen(false)} PaperProps={{ sx: { borderRadius: 3, p: 1 } }}>
				<DialogTitle sx={{ fontWeight: "bold", fontSize: "1.5rem" }}>Create a Post</DialogTitle>
				<DialogContent sx={{ display: "flex", flexDirection: "column", gap: 3, mt: 1 }}>
					<TextField label="Title" variant="outlined" fullWidth value={newPost.title} onChange={(e) => setNewPost({ ...newPost, title: e.target.value })} />
					<TextField label="What's on your mind?" multiline rows={4} variant="outlined" fullWidth value={newPost.content} onChange={(e) => setNewPost({ ...newPost, content: e.target.value })} />
					
					<Box sx={{ display: 'flex', gap: 2 }}>
						{/* Privacy Selection */}
						<Box sx={{ flex: 1 }}>
							<Typography variant="caption" color="text.secondary" fontWeight="bold" sx={{ mb: 1, display: 'block' }}>
								Privacy
							</Typography>
							<Select
								value={newPost.visibility || 'PUBLIC'}
								onChange={(e) => setNewPost({ ...newPost, visibility: e.target.value })}
								size="small"
								fullWidth
							>
								<MenuItem value="PUBLIC">🌎 Public (Everyone)</MenuItem>
								<MenuItem value="FRIENDS_ONLY">👥 Friends Only</MenuItem>
								<MenuItem value="ONLY_ME">🔒 Only Me</MenuItem>
							</Select>
						</Box>

						{/* Tags Selection */}
						<Box sx={{ flex: 2 }}>
							<Typography variant="caption" color="text.secondary" fontWeight="bold" sx={{ mb: 1, display: 'block' }}>
								Add Tags (Optional)
							</Typography>
                        <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                            {['Tournament', 'RAC', 'Stringing', 'Doubles', 'Equipment'].map(tag => {
                                const isSelected = newPost.tags.includes(tag);
                                return (
                                    <Chip 
                                        key={tag}
                                        label={tag}
                                        size="small"
                                        variant={isSelected ? "filled" : "outlined"}
                                        color={isSelected ? "primary" : "default"}
                                        onClick={() => {
                                            if (isSelected) {
                                                setNewPost(p => ({ ...p, tags: p.tags.filter(t => t !== tag) }));
                                            } else if (newPost.tags.length < 3) {
                                                setNewPost(p => ({ ...p, tags: [...p.tags, tag] }));
                                            }
                                        }}
                                        sx={{ cursor: 'pointer' }}
                                    />
                                );
                            })}
                        </Box>
                    </Box>
					</Box>

                    <Box>
						<input accept="image/*" style={{ display: "none" }} id="post-image-upload" type="file" multiple onChange={(e) => {
							const files = Array.from(e.target.files);
							if (files.length > 4) return alert("Maximum 4 images allowed");
							setPostImages(files);
						}} />
						<label htmlFor="post-image-upload">
							<Button variant="outlined" component="span" fullWidth color={postImages.length > 0 ? "success" : "primary"}>
								{postImages.length > 0 ? `Selected: ${postImages.length} image(s)` : "Attach Image(s) (Max 4)"}
							</Button>
						</label>
					</Box>
				</DialogContent>
				<DialogActions sx={{ px: 3, pb: 2 }}>
					<Button onClick={() => setIsModalOpen(false)} color="inherit" sx={{ fontWeight: "bold" }}>Cancel</Button>
					<Button onClick={handleSubmit} variant="contained" disabled={!isFormValid || isUploadingImage} sx={{ fontWeight: "bold", px: 4, borderRadius: 2 }}>
						{isUploadingImage ? <CircularProgress size={24} color="inherit" /> : "Post"}
					</Button>
				</DialogActions>
			</Dialog>
		</Box>
	);
}

import React from 'react';
import { render, screen, waitFor } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { BrowserRouter } from 'react-router-dom';
import Forum from './Forum';
import apiFetch from '../utils/api';
import { AuthContext } from '../context/AuthContext';

// Mock the API fetch utility
vi.mock('../utils/api', () => ({
    default: vi.fn()
}));

// Mock Masonry because JSDOM doesn't support complex CSS grid rendering well
vi.mock('@mui/lab/Masonry', () => ({
    default: ({ children }) => (
        <div data-testid="masonry-mock">
            {children}
        </div>
    )
}));

// Mock PostCard to prevent full deep rendering
vi.mock('../components/PostCard', () => ({
    default: ({ post }) => (
        <div data-testid={`post-card-${post._id}`}>
            <h3>{post.title}</h3>
            <p>{post.content}</p>
        </div>
    )
}));

const mockUser = { id: 'user1', name: 'Test User' };

describe('Forum Page Component (Community Hub)', () => {
    beforeEach(() => {
        vi.clearAllMocks();
        // Setup default intersection observer
        const mockIntersectionObserver = vi.fn();
        mockIntersectionObserver.mockReturnValue({
            observe: () => null,
            unobserve: () => null,
            disconnect: () => null
        });
        window.IntersectionObserver = mockIntersectionObserver;
    });

    const renderWithProviders = () => {
        return render(
            <AuthContext.Provider value={{ user: mockUser, token: 'fake-token' }}>
                <BrowserRouter>
                    <Forum />
                </BrowserRouter>
            </AuthContext.Provider>
        );
    };

    it('displays loading skeletons initially', () => {
        apiFetch.mockImplementation(() => new Promise(resolve => setTimeout(resolve, 1000)));
        const { container } = renderWithProviders();
        
        const skeletons = container.querySelectorAll('.MuiSkeleton-root');
        expect(skeletons.length).toBeGreaterThan(0);
    });

    it('renders empty state when no activity is found', async () => {
        apiFetch.mockResolvedValue({
            ok: true,
            json: async () => ({ feed: [], hasMore: false })
        });

        renderWithProviders();

        await waitFor(() => {
            expect(screen.getByText(/No activity found/i)).toBeInTheDocument();
        });
    });

    it('renders ActivityFeed items when data is loaded', async () => {
        const mockFeed = [
            {
                _id: 'feed1',
                type: 'post',
                referenceId: 'post1',
                title: 'Anyone down for singles?',
                content: 'Need a hitting partner.',
                authorId: 'user2',
                authorName: 'John Doe',
                likes: 0,
                comments: 0,
                createdAt: new Date().toISOString()
            }
        ];

        apiFetch.mockResolvedValue({
            ok: true,
            json: async () => ({ feed: mockFeed, hasMore: false })
        });

        renderWithProviders();

        await waitFor(() => {
            expect(screen.getByText('Anyone down for singles?')).toBeInTheDocument();
            expect(screen.getByText('Need a hitting partner.')).toBeInTheDocument();
        });
    });
});

import React from "react";
import { Box, Typography, Button, Container, Grid, Paper, useTheme } from "@mui/material";
import { motion } from "framer-motion";
import { useNavigate } from "react-router-dom";

export default function Landing() {
	const theme = useTheme();
	const navigate = useNavigate();

	const containerVariants = {
		hidden: { opacity: 0 },
		visible: {
			opacity: 1,
			transition: { staggerChildren: 0.2, delayChildren: 0.1 },
		},
	};

	const itemVariants = {
		hidden: { y: 30, opacity: 0 },
		visible: {
			y: 0,
			opacity: 1,
			transition: { type: "spring", stiffness: 100 },
		},
	};

	return (
		<Box sx={{ minHeight: "100vh", pt: { xs: 8, md: 12 }, pb: 8 }}>
			<Container maxWidth="lg" component={motion.div} variants={containerVariants} initial="hidden" animate="visible">
				{/* Hero Section */}
				<Box sx={{ textAlign: "center", mb: 8 }}>
					<motion.img
						src="/icon.jpg"
						alt="GMU Badminton"
						style={{ width: 120, height: 120, borderRadius: 24, marginBottom: 24, boxShadow: "0px 12px 24px rgba(0,0,0,0.2)" }}
						initial={{ scale: 0.8, opacity: 0 }}
						animate={{ scale: 1, opacity: 1 }}
						transition={{ type: "spring", bounce: 0.5 }}
					/>
					<motion.div variants={itemVariants}>
						<Typography variant="h2" fontWeight="900" sx={{ mb: 2, background: "linear-gradient(45deg, #006633, #FFCC33)", WebkitBackgroundClip: "text", WebkitTextFillColor: "transparent" }}>
							Mason Badminton Connect
						</Typography>
					</motion.div>
					<motion.div variants={itemVariants}>
						<Typography variant="h6" color="text.secondary" sx={{ mb: 4, maxWidth: 600, mx: "auto" }}>
							A student-run community platform for George Mason University badminton players. Connect, rank up, and hit the courts.
						</Typography>
					</motion.div>
					<motion.div variants={itemVariants}>
						<Button
							variant="contained"
							color="primary"
							size="large"
							onClick={() => navigate("/auth")}
							sx={{ py: 1.5, px: 4, borderRadius: 8, fontSize: "1.1rem", fontWeight: "bold", textTransform: "none", boxShadow: "0 8px 16px rgba(0, 102, 51, 0.3)" }}
						>
							Join the Club
						</Button>
					</motion.div>
				</Box>

				{/* Features Grid */}
				<Box sx={{ 
					display: 'grid', 
					gridTemplateColumns: { xs: '1fr', sm: 'repeat(auto-fit, minmax(280px, 1fr))' }, 
					gap: 4, 
					mt: 6 
				}}>
					{[
						{ title: "Live RAC Status", desc: "Instantly see if courts are open before you walk all the way to the gym.", icon: "🏸" },
						{ title: "Elo Leaderboards", desc: "Climb the ranks. Challenge players to official matches and prove you're the best on campus.", icon: "🏆" },
						{ title: "Active Forum", desc: "Find doubles partners, discuss gear, and organize late-night smash sessions.", icon: "💬" },
						{ title: "Player Profiles", desc: "Show off your racket, playstyle, and win streaks to the entire university.", icon: "🎴" }
					].map((feature, i) => (
						<motion.div key={i} variants={itemVariants} whileHover={{ y: -8 }} style={{ height: "100%" }}>
							<Paper elevation={0} sx={{ 
								p: 4, 
								height: "100%", 
								borderRadius: "24px", 
								backgroundColor: "background.paper", 
								border: "1px solid", 
								borderColor: "divider", 
								display: "flex", 
								flexDirection: "column", 
								alignItems: "flex-start", 
								textAlign: "left",
								boxShadow: "0 10px 30px rgba(0,0,0,0.03)",
								transition: "box-shadow 0.3s ease"
							}}>
								<Box sx={{ fontSize: "2.5rem", mb: 2, background: "rgba(0, 102, 51, 0.1)", p: 2, borderRadius: "16px", display: "inline-flex" }}>
									{feature.icon}
								</Box>
								<Typography variant="h5" fontWeight="bold" sx={{ mb: 1 }}>{feature.title}</Typography>
								<Typography variant="body1" color="text.secondary" sx={{ lineHeight: 1.6 }}>{feature.desc}</Typography>
							</Paper>
						</motion.div>
					))}
				</Box>
			</Container>
		</Box>
	);
}

